// Joins the database scripts into ONE file that can be pasted into the Supabase SQL editor in a single go.
//
//   node scripts/build-setup-sql.js
//
// It writes supabase/setup_all.sql. Do not edit that file by hand: change the scripts below (or
// src/data/madibaz-sport.json and run scripts/generate-sport-seed.js) and build it again.

const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');

// The order matters: everything after the first file uses the role helpers it creates.
const parts = [
  ['supabase/campus_features.sql', 'Tables, staff rules, tribes and chat, shuttle times, sport & gym, digital readiness'],
  ['supabase/migrations/20260919213000_coordinator_crud_policies.sql', 'Coordinator repair: clears leftover rules so staff can add, edit and delete'],
  ['supabase/coordinator_content.sql', 'Coordinator content'],
  ['supabase/migrations/20260919120000_it_programmes.sql', 'School of IT programmes and advisors'],
  ['supabase/migrations/20260919130000_event_schedule.sql', 'Campus events schedule: date, time, cost and sign-up link'],
  ['supabase/hod.sql', 'Head of department: programme information, expectations, assignments, resources, contacts'],
  ['supabase/migrations/20260919140000_sport_gym_madibaz.sql', 'Sport & gym: the real Madibaz clubs and how to join'],
  ['supabase/migrations/20260919150000_shuttle_times_2026.sql', 'Shuttle times: the real 2026 Gqeberha schedule'],
  ['supabase/migrations/20260920100000_emergency_contacts.sql', 'Emergency contacts: the national help numbers, editable by staff'],
  ['supabase/mentor_groups.sql', 'Mentor groups, join requests and QR codes'],
];

const read = (file) => fs.readFileSync(path.join(root, file), 'utf8').replace(/\r\n/g, '\n').trimEnd();

const sections = parts.map(([file, what], index) => {
  const bar = '-- ' + '='.repeat(75);
  return `${bar}\n-- PART ${index + 1} OF ${parts.length}: ${file}\n-- ${what}\n${bar}\n\n${read(file)}\n`;
});

const header = `-- Campus Companion: complete database setup, in one file.
--
-- GENERATED by scripts/build-setup-sql.js. Do not edit this file, change the scripts it is built from.
--
-- HOW TO USE
--   1. Supabase dashboard -> SQL Editor -> New query.
--   2. Paste this whole file and press Run.
--   3. It is safe to run again later. It never overwrites content that staff have edited.
--   4. Give each staff member their role (see supabase/set_roles.sql), then have them sign out and back in.
--
-- If part of it fails, Supabase normally undoes the whole run and shows the error, which names the
-- statement that failed. Send that error to whoever maintains the app.
--
-- WHAT IT SETS UP
${parts.map(([file, what], index) => `--   ${index + 1}. ${what}`).join('\n')}
`;

const out = header + '\n' + sections.join('\n') + '\n';
const target = path.join(root, 'supabase/setup_all.sql');
fs.writeFileSync(target, out.replace(/\n/g, '\r\n'));
console.log(`Wrote ${path.relative(root, target)} (${out.split('\n').length} lines, ${parts.length} parts)`);
